using System;using System.IO;using System.Net;using System.Security.Cryptography;using System.Threading;using System.Threading.Tasks;using TrayLeaf;
class Version100DownloadTests{
 static int passed,failed;static void Check(bool yes,string n){Console.WriteLine((yes?"PASS ":"FAIL ")+n);if(yes)passed++;else failed++;}static string Digest(byte[] bytes){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","");}
 static int Main(string[] args){try{return Run(args[0]).GetAwaiter().GetResult();}catch(Exception ex){Console.Error.WriteLine(ex);return 2;}}
 static async Task<int> Run(string path){Directory.CreateDirectory(path);byte[] content=System.Text.Encoding.UTF8.GetBytes("isolated installer download fixture - not executable");var socket=new System.Net.Sockets.TcpListener(IPAddress.Loopback,0);socket.Start();int port=((IPEndPoint)socket.LocalEndpoint).Port;socket.Stop();string origin="http://127.0.0.1:"+port+"/";using(var server=new HttpListener()){server.Prefixes.Add(origin);server.Start();bool stop=false;var serve=Task.Run(async delegate{while(!stop){HttpListenerContext context;try{context=await server.GetContextAsync();}catch{break;}if(context.Request.Url.AbsolutePath=="/slow"){Task.Run(async delegate{await Task.Delay(600);try{context.Response.Close();}catch{}});continue;}try{context.Response.ContentLength64=content.Length;await context.Response.OutputStream.WriteAsync(content,0,content.Length);context.Response.Close();}catch{}}});
  try{var release=new ReleaseInfo{Tag="v1.0.1",AssetName="Fixture.msi",DownloadUrl=origin+"good",Digest=Digest(content),Size=content.Length};int progress=-1;string file=await UpdateService.Download(release,path,n=>progress=n,CancellationToken.None);Check(File.Exists(file)&&UpdateService.VerifyDigest(file,release.Digest),"download-valid-hash-accepted");Check(progress>=0,"download-progress-reported");File.Delete(file);
   release.Digest=new string('0',64);bool blocked=false;try{await UpdateService.Download(release,path,null,CancellationToken.None);}catch(IOException ex){blocked=ex.Message.Contains("SHA-256");}Check(blocked,"download-corrupt-payload-rejected");Check(Directory.GetFiles(path,"*.part").Length==0,"partial-files-removed-after-failure");release.Digest="";blocked=false;try{await UpdateService.Download(release,path,null,CancellationToken.None);}catch(IOException ex){blocked=ex.Message.Contains("未提供");}Check(blocked,"download-missing-trusted-hash-rejected-before-request");
   bool timeout=false;try{await UpdateService.GetText(origin+"slow",100,CancellationToken.None);}catch(IOException ex){timeout=ex.Message.Contains("超时");}Check(timeout,"metadata-timeout-cancels-request");
   var cancel=new CancellationTokenSource();cancel.Cancel();bool cancelled=false;release.Digest=Digest(content);try{await UpdateService.Download(release,path,null,cancel.Token);}catch(Exception){cancelled=true;}Check(cancelled,"download-cancellation-supported");Check(Directory.GetFiles(path,"*.part").Length==0,"cancelled-partial-cleaned");
  }finally{stop=true;server.Stop();}await serve;}
  Console.WriteLine("RESULT passed="+passed+" failed="+failed);return failed==0?0:1;
 }
}
